import java.nio.file.*;import java.lang.reflect.*;public class ExtractConstants {public static void main(String[] args)throws Exception{Path dir=Path.of(args[1]);Files.createDirectories(dir);for(Field f:Class.forName(args[0]).getDeclaredFields()){if(f.getType()!=String.class||!Modifier.isStatic(f.getModifiers()))continue;f.setAccessible(true);Files.writeString(dir.resolve(f.getName()+".txt"),(String)f.get(null));System.out.println(f.getName());}}}